async function readPopup(html,epoch,{seconds=readingMode,cue='card',label='Time to read',pauseWhenHidden=false}={}){
 const reader=$('card-reader');reader.innerHTML=html;reader.classList.remove('hidden');document.body.classList.add('reading-card');$('turn-panel').querySelector('.eyebrow').textContent=label;playCue(cue);syncSound();
 let tick,startTick,remaining=seconds==='manual'?null:Number(seconds)*1000,lastTick=performance.now(),finished=false;
 try{await new Promise(resolve=>{
 const finish=()=>{if(finished)return;finished=true;resolve();};cardWait={resolve:finish,onVisible:pauseWhenHidden?()=>{lastTick=performance.now();playCue(cue);}:null,resetClock:()=>{lastTick=performance.now();}};
 const button=reader.querySelector('[data-action="continue-card"]');button.focus({preventScroll:true});
 if(remaining!==null){const total=remaining;$('reading-countdown').textContent='Continuing in '+Math.ceil(remaining/1000)+'s · or continue now';const start=()=>{lastTick=performance.now();tick=setInterval(()=>{const now=performance.now();if(!pauseWhenHidden||!document.hidden)remaining-=now-lastTick;lastTick=now;if(epoch!==animationEpoch){finish();return;}$('reading-countdown').textContent='Continuing in '+Math.max(0,Math.ceil(remaining/1000))+'s · or continue now';$('reading-progress').style.width=Math.max(0,remaining/total*100)+'%';if($('reading-ring'))$('reading-ring').style.strokeDashoffset=String(100-remaining/total*100);if($('reading-seconds'))$('reading-seconds').textContent=String(Math.max(0,Math.ceil(remaining/1000)));if(remaining<=0)finish();},150);};if($('reading-seconds'))$('reading-seconds').textContent=String(Math.ceil(remaining/1000));startTick=setTimeout(start,motion&&reader.querySelector('.draw-card:not(.recalled-card)')?650:0);}else{$('reading-progress').style.width='100%';reader.querySelector('.continue-timer')?.classList.add('hidden');}
 });}finally{clearInterval(tick);clearTimeout(startTick);cardWait=null;reader.classList.add('hidden');reader.innerHTML='';document.body.classList.remove('reading-card');}
}
