 for(const c of event.changes){const row=document.querySelector(`[data-player="${c.player}"]`);if(!row)continue;row.classList.add(c.amount>0?'money-gain':'money-loss');const floating=document.createElement('span');floating.className='cash-float '+(c.amount>0?'gain':'loss');floating.setAttribute('aria-hidden','true');floating.textContent=(c.amount>0?'+':'−')+money(Math.abs(c.amount));row.appendChild(floating);countCash(row.querySelector('.cash-amount'),old[c.player]??c.balance-c.amount,c.balance,epoch);}
 const notice=$('money-notice');notice.className='money-notice visible';notice.innerHTML=receiptMarkup(event);$('toast').classList.add('hidden');$('turn-panel').querySelector('.eyebrow').textContent='Money at the table';$('turn-panel').querySelector('.turn-description').textContent=event.reason;
