 if(motion&&token){const a=token.animate([{opacity:1},{opacity:0,transform:token.style.transform+' translateY(20px) scale(.7)'}],{duration:650,fill:'forwards'});a.finished.catch(()=>{}).then(()=>{token.style.opacity='0';a.cancel();});}else token?.style.setProperty('opacity','0');
 displayOut[event.player]=true;players();
