document.addEventListener('keydown',e=>{if(!e.target.closest?.('[data-action="sound"]'))void sound.unlock().then(syncSound);if(cardWait){if(e.key==='Escape'||((e.code==='Space'||e.key==='Enter')&&!['BUTTON','INPUT','SELECT'].includes(e.target.tagName))){e.preventDefault();continueCard();return;}if(e.key==='Tab'){const buttons=[...$('card-reader').querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target.closest?.('[data-highlight-player]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.closest('[data-highlight-player]').click();return;}if(busy)return;if(e.target.closest?.('[data-space]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.closest('[data-space]').dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}if(e.key==='Escape'&&modal&&!(modal==='setup'&&firstRun)){if(modal==='deed')void putDeedBack();else closeModal();return;}if(modal&&e.key==='Tab'){let nodes=[...$('modal-root').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,summary,a[href]')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if(e.code!=='Space'||modal||['INPUT','SELECT','TEXTAREA','BUTTON','A'].includes(e.target.tagName)||game.player.bot)return;if(game.s.phase==='roll'||game.s.phase==='end'){e.preventDefault();act(game.s.phase==='roll'?'roll':'end');}});
